 public void ShowLocomotionOptions(bool visible){ShowTrainingOptions(false);if(locomotionOptions==null)return;if(visible&&!motionTuning.DeveloperTuningEnabled)return;if(visible){ShowInputOptions(false);OptionLocomotionVisible=true;DeveloperOptionVisible=true;foreach(Transform child in optionPanel){bool keep=child.name=="Title"||child.name=="Close"||child.name=="Pause"||(child.name=="NavDummy"||child.name=="NavInputs"||child.name=="NavLocomotion"||child.name=="NavComparison"||child.name=="NavTraining"||child.name=="NavTitle")||child.name=="LocomotionSettings";child.gameObject.SetActive(keep);}locomotionOptions.SetActive(true);SyncMotion();RestartPreview(false);motionScroll.normalizedPosition=new Vector2(0,1);LayoutOption(hudWidth,hudHeight);}else{OptionLocomotionVisible=false;DeveloperOptionVisible=false;locomotionOptions.SetActive(false);}}
 void SyncMotion(){if(motionTuning==null)return;syncingMotion=true;var s=motionTuning.Requested;string[] values={s.backstepFrames.ToString(),s.backstepDistance.ToString("0.###",CultureInfo.InvariantCulture),s.pose1EndFrame.ToString(),s.pose2EndFrame.ToString(),s.backstepFrames.ToString(),s.jumpHeight.ToString("0.###",CultureInfo.InvariantCulture),s.jumpAirFrames.ToString()};for(int i=0;i<7;i++)motionFields[i].SetTextWithoutNotify(values[i]);syncingMotion=false;motionDraftValid=true;motionError.text="";}
 void MotionEdited(int index){if(syncingMotion)return;motionDraftValid=false;var s=motionTuning.Requested.Copy();if(!int.TryParse(motionFields[0].text,out s.backstepFrames)||!float.TryParse(motionFields[1].text,NumberStyles.Float,CultureInfo.InvariantCulture,out s.backstepDistance)||!int.TryParse(motionFields[2].text,out s.pose1EndFrame)||!int.TryParse(motionFields[3].text,out s.pose2EndFrame)||!float.TryParse(motionFields[5].text,NumberStyles.Float,CultureInfo.InvariantCulture,out s.jumpHeight)||!int.TryParse(motionFields[6].text,out s.jumpAirFrames)){motionError.text="Enter numeric values; invalid edits do not change the motor";return;}
  if(index==4){if(!int.TryParse(motionFields[4].text,out s.backstepFrames)){motionError.text="Pose 3 end must be an integer";return;}}
  if(!motionTuning.Apply(s,out var error)){motionError.text=error;return;}syncingMotion=true;motionFields[0].SetTextWithoutNotify(s.backstepFrames.ToString());motionFields[4].SetTextWithoutNotify(s.backstepFrames.ToString());syncingMotion=false;motionDraftValid=true;motionError.text="Valid; preview updated";RestartPreview(index>=5);
 }
