 void TickLocomotionOptions(){if(!OptionVisible||!OptionLocomotionVisible||motionTuning==null)return;var s=motionTuning.Requested;var view=player.GetComponent<ArmoredStaticPoseView>();int total=previewJump?s.jumpAirFrames:s.backstepFrames;previewFrame=Mathf.FloorToInt((Time.unscaledTime-previewStart)*60)%(total+24);float f=Mathf.Min(previewFrame,total),t=f/total;bool active=previewFrame<total;
