  float scale=Mathf.Clamp((motionGround.anchoredPosition.y*-1-315)/(previewJump?s.jumpHeight+2.3f:2.3f),12,52);var r=motionGhost.rectTransform;r.pivot=sprite.pivot/sprite.rect.size;r.sizeDelta=sprite.rect.size/sprite.pixelsPerUnit*scale*view.CalibratedVisualScale;r.anchorMin=r.anchorMax=new Vector2(0,1);float y=previewJump&&active?4*s.jumpHeight*t*(1-t)*scale:0;float x=previewJump?260:300-s.backstepDistance*t*scale;r.anchoredPosition=new Vector2(x,-(motionGround.anchoredPosition.y*-1)+y);
